data class CommitInfo (
    var `id`: kotlin.String
    , 
    var `summary`: kotlin.String
    , 
    var `author`: kotlin.String
    , 
    var `timeMs`: kotlin.Long
    
){
    

    

    
    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeCommitInfo: FfiConverterRustBuffer<CommitInfo> {
    override fun read(buf: ByteBuffer): CommitInfo {
        return CommitInfo(
            FfiConverterString.read(buf),
            FfiConverterString.read(buf),
            FfiConverterString.read(buf),
            FfiConverterLong.read(buf),
        )
    }

    override fun allocationSize(value: CommitInfo) = (
            FfiConverterString.allocationSize(value.`id`) +
            FfiConverterString.allocationSize(value.`summary`) +
            FfiConverterString.allocationSize(value.`author`) +
            FfiConverterLong.allocationSize(value.`timeMs`)
    )

    override fun write(value: CommitInfo, buf: ByteBuffer) {
            FfiConverterString.write(value.`id`, buf)
            FfiConverterString.write(value.`summary`, buf)
            FfiConverterString.write(value.`author`, buf)
            FfiConverterLong.write(value.`timeMs`, buf)
    }
}



data class CompletionContext (
    var `kind`: CompletionKind
    , 
