sealed class Block {
    
    object Blank : Block()
    
    
    data class Heading(
        val `level`: kotlin.UByte, 
        val `text`: kotlin.String, 
        val `line`: kotlin.UInt) : Block()
        
    {
        

        companion object
    }
    
    data class ListItem(
        val `indent`: kotlin.UByte, 
        val `ordered`: kotlin.Boolean, 
        val `checked`: kotlin.Boolean?, 
        val `text`: kotlin.String, 
        val `line`: kotlin.UInt) : Block()
        
    {
        

        companion object
    }
    
    data class Quote(
        val `text`: kotlin.String, 
        val `line`: kotlin.UInt) : Block()
        
    {
        

        companion object
    }
    
