    {
        

        companion object
    }
    
    data class Code(
        val `lang`: kotlin.String, 
        val `text`: kotlin.String, 
        val `line`: kotlin.UInt) : Block()
        
    {
        

        companion object
    }
    
    data class Paragraph(
        val `text`: kotlin.String, 
        val `line`: kotlin.UInt) : Block()
        
    {
        

        companion object
    }
    

    

    
    


    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeBlock : FfiConverterRustBuffer<Block>{
    override fun read(buf: ByteBuffer): Block {
        return when(buf.getInt()) {
            1 -> Block.Blank
            2 -> Block.Heading(
                FfiConverterUByte.read(buf),
                FfiConverterString.read(buf),
                FfiConverterUInt.read(buf),
                )
            3 -> Block.ListItem(
                FfiConverterUByte.read(buf),
                FfiConverterBoolean.read(buf),
                FfiConverterOptionalBoolean.read(buf),
                FfiConverterString.read(buf),
                FfiConverterUInt.read(buf),
                )
            4 -> Block.Quote(
                FfiConverterString.read(buf),
                FfiConverterUInt.read(buf),
                )
            5 -> Block.Image(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                FfiConverterUInt.read(buf),
                )
            6 -> Block.Code(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                FfiConverterUInt.read(buf),
                )
            7 -> Block.Paragraph(
                FfiConverterString.read(buf),
                FfiConverterUInt.read(buf),
                )
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: Block): ULong = when(value) {
        is Block.Blank -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is Block.Heading -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterUByte.allocationSize(value.`level`)
                + FfiConverterString.allocationSize(value.`text`)
                + FfiConverterUInt.allocationSize(value.`line`)
            )
        }
        is Block.ListItem -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterUByte.allocationSize(value.`indent`)
                + FfiConverterBoolean.allocationSize(value.`ordered`)
                + FfiConverterOptionalBoolean.allocationSize(value.`checked`)
                + FfiConverterString.allocationSize(value.`text`)
                + FfiConverterUInt.allocationSize(value.`line`)
            )
        }
        is Block.Quote -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`text`)
                + FfiConverterUInt.allocationSize(value.`line`)
            )
        }
        is Block.Image -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`src`)
                + FfiConverterString.allocationSize(value.`alt`)
                + FfiConverterUInt.allocationSize(value.`line`)
            )
        }
        is Block.Code -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`lang`)
                + FfiConverterString.allocationSize(value.`text`)
                + FfiConverterUInt.allocationSize(value.`line`)
            )
        }
        is Block.Paragraph -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`text`)
                + FfiConverterUInt.allocationSize(value.`line`)
            )
        }
    }

    override fun write(value: Block, buf: ByteBuffer) {
        when(value) {
            is Block.Blank -> {
                buf.putInt(1)
                Unit
            }
            is Block.Heading -> {
                buf.putInt(2)
                FfiConverterUByte.write(value.`level`, buf)
                FfiConverterString.write(value.`text`, buf)
                FfiConverterUInt.write(value.`line`, buf)
                Unit
            }
            is Block.ListItem -> {
                buf.putInt(3)
                FfiConverterUByte.write(value.`indent`, buf)
                FfiConverterBoolean.write(value.`ordered`, buf)
                FfiConverterOptionalBoolean.write(value.`checked`, buf)
                FfiConverterString.write(value.`text`, buf)
                FfiConverterUInt.write(value.`line`, buf)
                Unit
            }
            is Block.Quote -> {
                buf.putInt(4)
                FfiConverterString.write(value.`text`, buf)
                FfiConverterUInt.write(value.`line`, buf)
                Unit
            }
            is Block.Image -> {
                buf.putInt(5)
                FfiConverterString.write(value.`src`, buf)
                FfiConverterString.write(value.`alt`, buf)
                FfiConverterUInt.write(value.`line`, buf)
                Unit
            }
            is Block.Code -> {
                buf.putInt(6)
                FfiConverterString.write(value.`lang`, buf)
                FfiConverterString.write(value.`text`, buf)
                FfiConverterUInt.write(value.`line`, buf)
                Unit
            }
            is Block.Paragraph -> {
                buf.putInt(7)
                FfiConverterString.write(value.`text`, buf)
                FfiConverterUInt.write(value.`line`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}






