        val `marker`: kotlin.String) : ListAction()
        
    {
        

        companion object
    }
    
    /**
     * The current item is empty: replace the marker on this line with `marker`
     * (an empty string ends the list, a shorter one outdents a level).
     */
    data class Replace(
        val `marker`: kotlin.String) : ListAction()
        
    {
        

        companion object
    }
    
    /**
     * Not a list item.
     */
    object None : ListAction()
    
    

    

    
    


    companion object
}

